		return fmt.Errorf("open source: %w", err)
	}
	defer src.Close()

	info, err := src.Stat()
	if err != nil {
		return fmt.Errorf("stat source: %w", err)
	}
	totalSize := info.Size()

	dest, err := os.Create(destPath)
	if err != nil {
		return fmt.Errorf("create destination: %w", err)
	}
	defer func() {
		dest.Close()
		if ctx.Err() != nil {
			os.Remove(destPath)
		}
	}()

	if progress != nil {
		progress(0.0, "Starting export...")
	}

	const bufSize = 32 * 1024
	buf := make([]byte, bufSize)
	var copied int64

	for {
		if err := ctx.Err(); err != nil {
			return err
		}

		n, readErr := src.Read(buf)
		if n > 0 {
			written, writeErr := dest.Write(buf[:n])
			if writeErr != nil {
				return fmt.Errorf("write destination: %w", writeErr)
			}
			copied += int64(written)

			if progress != nil && totalSize > 0 {
				pct := float64(copied) / float64(totalSize)
				if pct > 1.0 {
					pct = 1.0
				}
				progress(pct, fmt.Sprintf("Exported %d / %d bytes", copied, totalSize))
			}
		}

		if readErr == io.EOF {
			break
		}
		if readErr != nil {
			return fmt.Errorf("read source: %w", readErr)
		}
	}

	if progress != nil {
		progress(1.0, "Export complete")
	}

	return nil
}

